pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool, ERC721, IStolenNftOracle} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function protocolFeeRate() external pure returns (uint16) {
        return 0;
    }

    receive() external payable {}

    function testFuzz_property(uint256 vb, uint256 vn, uint256 w, uint256 id) public {
        vb = bound(vb, 2, 1e24);
        vn = bound(vn, 1, 1e6);
        w = bound(w, 1e18, 2e18);
        id = bound(id, 1, 1e6);

        TestNFT n = new TestNFT();
        n.mint(address(this), id);

        c.initialize(
            address(0),
            address(n),
            uint128(vb),
            uint128(vn),
            0,
            0,
            bytes32(0),
            false,
            false
        );

        uint256 output = (w * vb) / (vn + w);
        vm.assume(output > 0 && output < vb);

        vm.deal(address(c), output * 2);
        n.approve(address(c), id);

        uint256[] memory ids = new uint256[](1);
        ids[0] = id;
        uint256[] memory ws = new uint256[](1);
        ws[0] = w;
        bytes32[] memory p = new bytes32[](0);
        bool[] memory f = new bool[](0);
        PrivatePool.MerkleMultiProof memory mp = PrivatePool.MerkleMultiProof({proof: p, flags: f});

        c.sell(ids, ws, mp, new IStolenNftOracle.Message[](0));

        assertTrue(c.virtualBaseTokenReserves() < vb);
    }
}

contract TestNFT is ERC721 {
    constructor() ERC721("t", "T") {}

    function mint(address to, uint256 id) external {
        _mint(to, id);
    }

    function tokenURI(uint256) public pure override returns (string memory) {
        return "";
    }
}
